namespace RonSijm.FluidHumidifier.Factories.Glue;

public class IntegrationResourcePropertyFactory(string resourceName = null, Action<Humidifier.Glue.IntegrationResourceProperty> factoryAction = null) : ResourceFactory<Humidifier.Glue.IntegrationResourceProperty>(resourceName)
{

    internal InnerIntegrationResourcePropertyTargetProcessingPropertiesFactory TargetProcessingPropertiesFactory { get; set; }

    internal InnerIntegrationResourcePropertySourceProcessingPropertiesFactory SourceProcessingPropertiesFactory { get; set; }

    protected override Humidifier.Glue.IntegrationResourceProperty Create()
    {
        var integrationResourcePropertyResult = CreateIntegrationResourceProperty();
        factoryAction?.Invoke(integrationResourcePropertyResult);

        return integrationResourcePropertyResult;
    }

    private Humidifier.Glue.IntegrationResourceProperty CreateIntegrationResourceProperty()
    {
        var integrationResourcePropertyResult = new Humidifier.Glue.IntegrationResourceProperty
        {
            GivenName = InputResourceName,
        };

        return integrationResourcePropertyResult;
    }
    public override void CreateChildren(Humidifier.Glue.IntegrationResourceProperty result)
    {
        base.CreateChildren(result);

        result.TargetProcessingProperties ??= TargetProcessingPropertiesFactory?.Build();
        result.SourceProcessingProperties ??= SourceProcessingPropertiesFactory?.Build();
    }

} // End Of Class

